def install(url):
    return f"""<h2>1. Installer et ouvrir l'application</h2>
    <p>Aucun téléchargement dans un magasin d'applications : l'application s'ouvre dans le navigateur et s'installe sur l'écran d'accueil en deux gestes.</p>
    <div class="g2"><div class="k ok"><b>Android (Chrome)</b><ol><li>Ouvrez le lien <b>{url}</b>.</li><li>Touchez le menu ⋮ puis <b>« Installer l'application »</b> (ou « Ajouter à l'écran d'accueil »).</li><li>Confirmez : l'icône STAR apparaît sur l'écran d'accueil.</li></ol></div>
    <div class="k ok"><b>iPhone / iPad (Safari)</b><ol><li>Ouvrez le lien dans <b>Safari</b>.</li><li>Touchez le bouton <b>Partager</b> (carré avec une flèche).</li><li>Choisissez <b>« Sur l'écran d'accueil »</b> puis « Ajouter ».</li></ol></div></div>
    <h3>À savoir avant de commencer</h3>
    <ul><li><b>Première ouverture avec connexion</b> : l'application se met en mémoire. Ensuite elle <b>fonctionne sans connexion</b>.</li><li>Autorisez la <b>caméra</b> quand le téléphone le demande (photos, scan de QR).</li><li>Le bouton <b>🔊 voix</b> en haut active la lecture à voix haute des étapes et des résultats (français). Il fonctionne selon les voix installées sur le téléphone.</li><li>Les données restent <b>sur l'appareil</b> : cette version de démonstration n'est reliée à aucun serveur.</li></ul>"""
def couv(titre, accent, sous, url, ph, pied):
    return f"""<div class="p cov" data-pied="{pied}"><div class="ph" style="background-image:url({ph})"></div><img class="lg" src="{LOGO}"><h1>{titre} <b>{accent}</b></h1><h2>Guide d'utilisation</h2><div class="sub">{sous}</div>
    <div class="lien"><div class="q" id="qr"></div><div><small>Ouvrir l'application</small><b>{url}</b><small>Scannez le QR avec l'appareil photo du téléphone</small></div></div><div class="ft">STAR ENTREPRISE · Brazzaville, République du Congo<br>Version de démonstration · 28 novembre 2026</div><div class="bandeau"></div></div>"""
def terrain():
    url = BASE + '/terrain-sur/'; pied = 'TERRAIN SÛR · guide d\'utilisation · STAR ENTREPRISE'
    P = [couv('TERRAIN', 'SÛR', 'Lire un terrain avant de construire. Pré-diagnostic par photo et questions guidées, suivi des chantiers, rapports vérifiables.', url, photo('terrain-sur/img/piste.jpg'), pied)]
    P.append(f"""<div class="p" data-pied="{pied}">{install(url)}
    <h3>À quoi sert l'application, et à quoi elle ne sert pas</h3>
    <div class="g2"><div class="k ok"><b>Elle sert à</b><ul><li>repérer vite les terrains à risque (érosion, eau, sol faible, pente, remblai)</li><li>expliquer le résultat en mots simples</li><li>garder des preuves datées et localisées</li><li>vérifier qu'un rapport est authentique</li></ul></div><div class="k ko"><b>Elle ne sert pas à</b><ul><li>mesurer la solidité réelle du sol</li><li>remplacer l'étude géotechnique</li><li>autoriser une construction</li></ul></div></div>
    <p><b>Une photo ne dit pas tout.</b> Seuls des sondages et des essais en laboratoire mesurent la portance d'un sol. TERRAIN SÛR fait le premier tri et oriente vers la bonne étude.</p><div class="bandeau"></div></div>""")
    P.append(f"""<div class="p" data-pied="{pied}"><h2>2. Analyser un terrain, pas à pas</h2>
    <div class="g3"><figure class="f"><img src="{img('terrain-sur','accueil.jpg')}" style="height:60mm"><figcaption><b>Accueil.</b> Touchez « Analyser un terrain ».</figcaption></figure><figure class="f"><img src="{img('terrain-sur','lecture.jpg')}" style="height:60mm"><figcaption><b>Photo.</b> L'application colore les surfaces.</figcaption></figure><figure class="f"><img src="{img('terrain-sur','questions.jpg')}" style="height:60mm"><figcaption><b>Questions.</b> Dix questions de terrain.</figcaption></figure></div>
    <ol style="margin-top:4mm"><li><span class="n">1</span><b>Choisissez le lieu et l'usage</b> : ville, quartier (facultatif), puis ce que vous voulez faire (maison, immeuble, route, drainage). Si un chantier est suivi, liez-le ici.</li><li><span class="n">2</span><b>Prenez la photo du sol.</b> Debout, appareil à hauteur de poitrine, orienté vers le sol, en plein jour, sans trop de ciel (environ 2 à 3 mètres de sol). Touchez « Prendre la photo ». Sans terrain sous la main, utilisez « Photos d'exemple ».</li><li><span class="n">3</span><b>Contrôlez la lecture.</b> L'application indique ce qu'elle voit (terre rouge, sable, eau, végétation) et vous prévient si la photo est floue, sombre ou si le sol est peu visible. Dans ce cas : « Refaire la photo ».</li><li><span class="n">4</span><b>Répondez aux dix questions</b> : pente, eau, ravines, test du boudin, fissures, voisinage, fleuve, remblai, drainage, plantes. Une question peut rester vide si vous ne savez pas.</li><li><span class="n">5</span><b>Touchez « Obtenir le diagnostic ».</b></li></ol>
    <div class="k"><b>La position GPS</b> est prise automatiquement (autorisez la localisation). Sans GPS, le relevé reste possible mais une alerte « position absente » sera inscrite.</div><div class="bandeau"></div></div>""")
    P.append(f"""<div class="p" data-pied="{pied}"><h2>3. Lire le résultat</h2>
    <div class="g2"><figure class="f"><img src="{img('terrain-sur','resultat.jpg')}" style="height:118mm"><figcaption>Niveau, score, risques par nature, raisons, actions.</figcaption></figure>
    <div><table><tr><th>Niveau</th><th>Ce que ça veut dire</th></tr><tr><td><b style="color:#1f8a4c">Favorable</b></td><td>Aucun signal bloquant. L'étude reste obligatoire.</td></tr><tr><td><b style="color:#d9a100">Vigilance</b></td><td>Points d'attention : étude indispensable avant de décider.</td></tr><tr><td><b style="color:#e07a1a">Risque élevé</b></td><td>Plusieurs signaux inquiétants : pas de travaux sans étude complète et protections.</td></tr><tr><td><b style="color:#c0392b">Critique</b></td><td>Ne pas construire en l'état : traiter d'abord le problème (eau, ravine, pente).</td></tr></table>
    <h3>Les cinq risques</h3><p>Érosion et ravinement · Eau et inondation · Portance du sol · Stabilité de pente · Remblai. Chaque point du score est justifié (« Pourquoi ce résultat ? »).</p><h3>La confiance</h3><p>Elle n'est jamais « élevée » : elle baisse si la photo est mauvaise ou si des questions restent vides.</p><h3>Règles de sécurité</h3><p>Dans les cas graves (grande ravine proche, ancienne décharge, terrain déjà inondé, affaissement visible), un niveau minimum est imposé.</p></div></div>
    <p><b>« 🔊 Écouter »</b> lit le résultat à voix haute. <b>« 🔒 Sceller dans le journal »</b> enregistre le relevé : il ne pourra plus être modifié sans que ça se voie. Après le scellé, <b>« 📄 Rapport PDF »</b> télécharge le rapport de deux pages avec QR code.</p><div class="bandeau"></div></div>""")
    P.append(f"""<div class="p" data-pied="{pied}"><h2>4. Suivre un chantier et lutter contre la fraude</h2>
    <p>Dans l'onglet <b>Chantiers</b>, créez un chantier <b>à l'endroit où vous vous trouvez</b>, avec sa date d'ordre de service. Chaque relevé lié est comparé automatiquement.</p>
    <table><tr><th>Alerte</th><th>Quand elle apparaît</th></tr><tr><td>Photo déjà utilisée</td><td>même fichier, ou même scène recadrée, déjà présent dans le journal</td></tr><tr><td>Photo ancienne</td><td>fichier de plus de 15 minutes présenté comme pris sur place ; image de galerie signalée</td></tr><tr><td>Mauvais lieu</td><td>position à plus de 300 m du chantier déclaré</td></tr><tr><td>Mauvaise date</td><td>photo antérieure à l'ordre de service</td></tr><tr><td>Position absente</td><td>GPS non autorisé ou indisponible</td></tr><tr><td>Photo inutilisable</td><td>floue, sombre ou éblouie</td></tr></table>
    <div class="g2"><figure class="f"><img src="{img('terrain-sur','journal.jpg')}" style="height:70mm"><figcaption><b>Journal verrouillé.</b> Chaque relevé porte l'empreinte du précédent. « Vérifier l'intégrité » contrôle toute la chaîne.</figcaption></figure><figure class="f"><img src="{img('terrain-sur','verif.jpg')}" style="height:70mm"><figcaption><b>Vérifier un rapport.</b> Saisissez le code ou scannez le QR : authentique, introuvable ou falsifié.</figcaption></figure></div>
    <div class="k">« ⚠ Simuler une falsification » sert à la démonstration : il modifie un relevé pour montrer que la chaîne se casse. Ne l'utilisez pas sur des relevés réels.</div>
    <h3>Le tableau de bord de l'État</h3><p>L'onglet <b>État</b> montre un plan par ville, les alertes et les chantiers « déclaré contre constaté ». <b>Toutes ses données sont fictives</b> dans cette version : elles servent à montrer ce que verrait l'administration.</p><div class="bandeau"></div></div>""")
    P.append(f"""<div class="p" data-pied="{pied}"><h2>5. Conseils, dépannage et limites</h2>
    <table><tr><th>Problème</th><th>Que faire</th></tr><tr><td>La photo est refusée comme floue ou sombre</td><td>Plein jour, appareil stable, 2 à 3 m de sol dans le cadre, sans ombre portée</td></tr><tr><td>« Position introuvable »</td><td>Activez la localisation du téléphone et autorisez le site ; sortez à l'air libre</td></tr><tr><td>Le bouton « Écouter » ne dit rien</td><td>Montez le volume, vérifiez qu'une voix française est installée dans les réglages du téléphone</td></tr><tr><td>Les photos d'exemple ne s'affichent pas hors connexion</td><td>Ouvrez l'application une première fois avec connexion</td></tr><tr><td>Je veux effacer mes relevés</td><td>Effacez les données du site dans les réglages du navigateur (les relevés sont sur l'appareil uniquement)</td></tr></table>
    <h3>Les limites à connaître</h3>
    <ul><li>Une photo <b>ne mesure pas</b> la solidité du sol : le résultat oriente, il ne prouve rien sur le sous-sol.</li><li>Les pondérations du moteur sont des repères de bon sens, <b>à faire valider par des géotechniciens</b> avant tout usage officiel.</li><li>Le contexte local (quartiers cités) vient de la presse et de documents publics : <b>ce n'est pas une carte officielle</b>.</li><li>Aucun serveur d'État n'est relié : la vérification d'un rapport se fait sur l'appareil.</li><li>Les contrôles anti-fraude locaux peuvent être contournés par un utilisateur déterminé ; un serveur et la signature des agents les renforceraient.</li><li>Les photos d'exemple ne viennent pas du Congo.</li></ul>
    <h3>Étapes obligatoires avant de construire</h3><ol><li>Étude géotechnique (sondages et essais) par un bureau d'études ou un laboratoire agréé.</li><li>Demande de permis de construire auprès de l'administration compétente.</li><li>Contrôle technique du chantier pendant toute la durée des travaux.</li></ol>
    <div style="margin-top:6mm;display:flex;align-items:center;gap:6mm;border-top:2px solid #d9b25a;padding-top:4mm"><img src="{LOGO_P}" style="width:16mm"><div><b>STAR ENTREPRISE</b><br><span class="mini">contact@starentreprise.com · WhatsApp +242 06 656 50 50 · Brazzaville, République du Congo</span></div></div><div class="bandeau"></div></div>""")
    return P, url
def hotel():
    url = BASE + '/hotel-reception/'; pied = 'CHECK-IN STAR · guide d\'utilisation · STAR ENTREPRISE'
    P = [couv('CHECK-IN', 'STAR', 'Du passeport à la chambre, sans papier. Lecture du passeport, enregistrement, attribution de la chambre et accusé en code QR.', url, photo('hotel-reception/img/hall.jpg'), pied)]
    P.append(f"""<div class="p" data-pied="{pied}">{install(url)}
    <h3>Pour qui, avec quoi</h3><p>CHECK-IN STAR est destiné à la <b>réception d'un hôtel</b> : tablette ou téléphone du réceptionniste. Le client n'a rien à installer : il reçoit son accusé par WhatsApp. Dans cette version, l'hôtel de démonstration compte <b>170 chambres sur 12 étages</b> ; les clients et séjours affichés sont <b>fictifs</b>.</p>
    <div class="k"><b>Rappel.</b> Les noms, séjours et chambres déjà occupées sont inventés. Les tarifs affichés sont des <b>repères relevés en ligne</b> (en dollars) : la direction saisit les vrais dans l'écran « Tarifs ».</div><div class="bandeau"></div></div>""")
    P.append(f"""<div class="p" data-pied="{pied}"><h2>2. Tableau de bord et menu</h2>
    <figure class="f"><img src="{img('check-in-star','tableau.jpg')}" style="height:84mm"><figcaption>Le tableau de bord : occupation, arrivées, départs, chambres à nettoyer, alertes et journal verrouillé.</figcaption></figure>
    <table><tr><th>Menu</th><th>À quoi il sert</th></tr><tr><td>🏨 <b>Tableau</b></td><td>L'état de l'hôtel : % d'occupation, arrivées et départs du jour, à nettoyer, alertes</td></tr><tr><td>🛂 <b>Arrivée</b></td><td>Enregistrer un client : passeport, séjour, chambre, accusé</td></tr><tr><td>🗺️ <b>Plan</b></td><td>Les 170 chambres en couleurs ; toucher une chambre pour agir</td></tr><tr><td>👥 <b>Séjours</b></td><td>Clients présents et réservés, recherche, départ</td></tr><tr><td>💎 <b>Tarifs</b></td><td>Prix par catégorie, taux du jour, nom de l'hôtel</td></tr><tr><td>🔐 <b>Vérifier</b></td><td>Contrôler l'accusé d'un client (code ou QR)</td></tr></table>
    <p class="mini">Le bouton « ▶ Démonstration automatique » déroule une arrivée complète tout seul. « ↺ Réinitialiser la démonstration » remet l'hôtel dans son état de départ.</p><div class="bandeau"></div></div>""")
    P.append(f"""<div class="p" data-pied="{pied}"><h2>3. Enregistrer une arrivée</h2>
    <div class="g2"><figure class="f"><img src="{img('check-in-star','passeport.jpg')}" style="height:62mm"><figcaption><b>Étape 1.</b> Passeport lu et vérifié.</figcaption></figure><figure class="f"><img src="{img('check-in-star','sejour.jpg')}" style="height:62mm"><figcaption><b>Étape 2.</b> Nombre de nuits et catégorie.</figcaption></figure></div>
    <h3><span class="n">1</span>Le passeport</h3>
    <p>Touchez <b>« Photographier le passeport »</b> et cadrez la page d'identité, en particulier les <b>deux lignes de chevrons « &lt;&lt;&lt; »</b> du bas. Posez le document à plat, sans reflet. L'application lit les lignes, remplit l'identité et contrôle la pièce : chiffres de contrôle, expiration, passeport déjà en séjour.</p>
    <ul><li>✔ <b>Pièce lue et vérifiée</b> : continuez.</li><li>⚠ <b>Pièce à contrôler</b> (chiffres faux, passeport expiré, déjà en séjour) : l'enregistrement est <b>bloqué</b>. Un responsable peut le débloquer avec « Contrôle manuel par un responsable » : la décision est inscrite au journal et au dossier du client.</li><li>Si la lecture échoue (photo floue), reprenez-la, ou <b>tapez les deux lignes à la main</b> dans la zone modifiable.</li><li>Pour s'entraîner : « Passeport d'exemple », « Passeport expiré », « Passeport falsifié ».</li></ul>
    <h3><span class="n">2</span>Le séjour</h3>
    <p>Touchez le <b>nombre de nuits</b> (1 à 30) ou changez les dates. Choisissez la <b>catégorie</b> : « Automatique » (la meilleure chambre disponible) ou un type précis. Notez le <b>numéro WhatsApp</b> du client pour l'accusé. Options : <b>étage élevé</b>, <b>accès mobilité réduite</b>, nombre de personnes. Touchez « Choisir la chambre ».</p><div class="bandeau"></div></div>""")
    P.append(f"""<div class="p" data-pied="{pied}"><h2>3. Enregistrer une arrivée (suite)</h2>
    <div class="g2"><figure class="f"><img src="{img('check-in-star','chambre.jpg')}" style="height:62mm"><figcaption><b>Étape 3.</b> Chambre attribuée, prix et raisons du choix.</figcaption></figure><figure class="f"><img src="{img('check-in-star','mobile-accuse.jpg')}" style="height:62mm"><figcaption><b>Étape 4.</b> L'accusé du client avec son QR.</figcaption></figure></div>
    <h3><span class="n">3</span>La chambre</h3>
    <p>L'application propose la meilleure chambre : <b>propre, libre pour toutes les nuits</b>, qui remplit au mieux le calendrier. Elle <b>explique son choix</b> et propose cinq alternatives (touchez-en une pour la préférer). Si la catégorie demandée est complète, un <b>surclassement</b> est proposé et signalé : à valider par la direction. Le prix du séjour s'affiche ; pour une suite « sur devis », saisissez le <b>tarif convenu par nuit</b>. Touchez <b>« Confirmer et enregistrer »</b>.</p>
    <h3><span class="n">4</span>L'accusé</h3>
    <p>Le client est enregistré, la chambre passe à « occupée » et l'arrivée est inscrite au journal. L'écran montre la carte d'accueil avec le <b>code QR</b>. Choisissez comment la remettre :</p>
    <table><tr><th>Bouton</th><th>Effet</th></tr><tr><td>💬 Envoyer sur WhatsApp</td><td>Ouvre la conversation avec le numéro saisi et le message prêt (chambre, dates, code). Le réceptionniste touche « envoyer ».</td></tr><tr><td>📤 Partager l'image du QR</td><td>Ouvre le partage du téléphone avec l'image du QR : choisissez WhatsApp ou SMS</td></tr><tr><td>⬇ Image (PNG)</td><td>Télécharge l'accusé en image</td></tr><tr><td>📄 Fiche d'enregistrement + accusé (PDF)</td><td>PDF de 2 pages : page 1 pour les archives de l'hôtel (identité, séjour, signatures), page 2 pour le client</td></tr></table>
    <div class="k"><b>Important.</b> L'envoi sur WhatsApp n'est pas 100 % automatique : l'application prépare le message, la personne appuie sur « envoyer ». Un envoi automatique demande un service officiel (WhatsApp Business ou SMS).</div><div class="bandeau"></div></div>""")
    P.append(f"""<div class="p" data-pied="{pied}"><h2>4. Au quotidien : plan, départs, tarifs, vérification</h2>
    <figure class="f"><img src="{img('check-in-star','plan.jpg')}" style="height:72mm"><figcaption>Le plan : vert libre · bleu occupée · orange départ aujourd'hui · jaune à nettoyer · violet arrivée prévue · gris maintenance.</figcaption></figure>
    <ul><li><b>Départ d'un client</b> : touchez sa chambre (ou « Séjours »), puis « Départ du client ». La chambre passe à <b>« à nettoyer »</b> et ne peut pas être attribuée avant d'être remise <b>propre</b> (« Marquer propre »).</li><li><b>Maintenance</b> : « Maintenance » retire la chambre de la vente ; « Fin de maintenance » la remet.</li><li><b>Tarifs</b> : saisissez vos prix en dollars et/ou en FCFA, et le <b>taux du jour</b> (1 $ = … FCFA). Sans taux, les totaux restent en dollars. Les repères affichés au départ viennent d'un hôtel de référence : remplacez-les.</li><li><b>Vérifier un accusé</b> : au restaurant, au spa ou à la porte, saisissez le code (ou scannez le QR par « Scanner un QR »). Résultats : <b>séjour valide</b>, terminé, pas encore commencé, <b>accusé altéré</b> (le sceau ne correspond plus) ou <b>inconnu</b>.</li><li><b>Journal verrouillé</b> : chaque arrivée et chaque départ porte l'empreinte du précédent ; « Vérifier l'intégrité » contrôle la chaîne.</li></ul>
    <h3>Données personnelles et sécurité</h3>
    <ul><li>La <b>photo du passeport n'est pas conservée</b> ; elle est lue sur l'appareil et rien n'est envoyé en ligne.</li><li>Les numéros de pièce sont <b>masqués</b> dans les listes et ne sont pas écrits en clair dans le journal.</li><li>Les données restent sur l'appareil. Un déploiement réel demandera un serveur sécurisé, des droits par rôle et la conformité avec la réglementation congolaise.</li></ul><div class="bandeau"></div></div>""")
    P.append(f"""<div class="p" data-pied="{pied}"><h2>5. Dépannage et limites</h2>
    <table><tr><th>Problème</th><th>Que faire</th></tr><tr><td>Le passeport n'est pas lu</td><td>Photo nette, plein éclairage, sans reflet, zone du bas entière dans le cadre ; sinon taper les deux lignes à la main</td></tr><tr><td>« Chiffres de contrôle faux » sur un vrai passeport</td><td>Souvent un caractère mal lu : corrigez le texte dans la zone modifiable, ou faites une nouvelle photo</td></tr><tr><td>« Aucune chambre disponible »</td><td>Changez les dates, la catégorie, ou retirez une préférence ; vérifiez les chambres « à nettoyer »</td></tr><tr><td>Le partage de l'image ne s'ouvre pas</td><td>Utilisez « Image (PNG) » puis envoyez le fichier depuis la galerie</td></tr><tr><td>Je veux repartir de zéro</td><td>Tableau → « Réinitialiser la démonstration »</td></tr></table>
    <h3>Ce que cette version ne fait pas encore</h3>
    <ul><li>Pas de <b>serrures connectées</b> : le QR est un accusé et une preuve de séjour, pas une clé de porte.</li><li>Pas de <b>paiement</b> ni de <b>facture</b>.</li><li>Pas de <b>serveur</b> : les données sont sur un seul appareil ; pas de plusieurs postes ni de sauvegarde.</li><li>Les <b>déclarations officielles</b> (fiche de police) ne sont pas branchées. La fiche d'enregistrement est un modèle à <b>faire valider avec les autorités et un conseil juridique</b>.</li><li>Les <b>tarifs</b> sont des repères en dollars relevés en ligne, hors taxes.</li></ul>
    <div style="margin-top:6mm;display:flex;align-items:center;gap:6mm;border-top:2px solid #d9b25a;padding-top:4mm"><img src="{LOGO_P}" style="width:16mm"><div><b>STAR ENTREPRISE</b><br><span class="mini">contact@starentreprise.com · WhatsApp +242 06 656 50 50 · Brazzaville, République du Congo</span></div></div><div class="bandeau"></div></div>""")
    return P, url
def rendre(P, url, sortie):
    qrscript = '<script>' + QRJS + '</script><script>var q=qrcode(0,"M");q.addData("' + url + '");q.make();document.getElementById("qr").innerHTML=q.createSvgTag(4,0);</script>'
    html = '<!doctype html><html lang="fr"><head><meta charset="utf-8"><style>' + CSS + '</style></head><body>' + ''.join(P) + qrscript + '</body></html>'
    tmp = '/tmp/guide-' + os.path.basename(sortie) + '.html'; open(tmp, 'w', encoding='utf-8').write(html)
    js = f"""const {{chromium}}=require('playwright');(async()=>{{const b=await chromium.launch();const p=await b.newPage();await p.goto('file://{tmp}');await p.waitForTimeout(800);
await p.pdf({{path:'{sortie}',format:'A4',printBackground:true,margin:{{top:'0',bottom:'0',left:'0',right:'0'}}}});await b.close();}})().catch(e=>{{console.error(e);process.exit(1)}});"""
    open('/tmp/guide-r.cjs', 'w').write(js); r = subprocess.run(['node', '/tmp/guide-r.cjs'], capture_output=True, text=True, cwd=ROOT)
    if r.returncode: print(r.stderr); sys.exit(1)
    print('OK', sortie, os.path.getsize(sortie) // 1024, 'Ko')
for nom, f in (('TERRAIN-SUR', terrain), ('CHECK-IN-STAR', hotel)):
    P, url = f(); rendre(P, url, os.path.join(D, f'GUIDE-UTILISATION-{nom}.pdf'))
